@override Widget build(BuildContext context){return Scaffold(appBar:AppBar(title:const Text('Gig Income')),body:Consumer<AppState>(builder:(context,appState,_){final incomes=List<GigIncome>.from(appState.myGigIncomes)..sort((a,b)=>b.date.compareTo(a.date));if(incomes.isEmpty)return const Center(child:Text('No gig income yet'));final now=DateTime.now();final monthIncomes=incomes.where((g)=>g.date.month==now.month&&g.date.year==now.year).toList();final totalMonth=monthIncomes.fold<double>(0,(s,g)=>s+g.totalAmount);final totalMiles=monthIncomes.fold<double>(0,(s,g)=>s+g.miles);final avg=totalMiles>0?totalMonth/totalMiles:0.0;return Column(children:[Padding(padding:const EdgeInsets.all(12),child:Material(color:const Color(0xFF1E1E1E),borderRadius:BorderRadius.circular(12),child:Padding(padding:const EdgeInsets.all(16),child:Row(mainAxisAlignment:MainAxisAlignment.spaceAround,children:[_sum('Month','\$${totalMonth.toStringAsFixed(2)}'),_sum('Miles',totalMiles.toStringAsFixed(1)),_sum('Avg/mi','\$${avg.toStringAsFixed(2)}')])))),Expanded(child:ListView.builder(itemCount:incomes.length,itemBuilder:(context,i){final g=incomes[i];return Padding(padding:const EdgeInsets.symmetric(horizontal:12,vertical:6),child:Material(color:const Color(0xFF1E1E1E),borderRadius:BorderRadius.circular(12),child:ListTile(title:Text('${g.platformName} • ${g.formattedTotal}'),subtitle:Text('${g.formattedDate} • ${g.miles.toStringAsFixed(1)} mi • ${g.payPerMile.toStringAsFixed(2)}/mi'),trailing:Row(mainAxisSize:MainAxisSize.min,children:[IconButton(icon:const Icon(Icons.edit),onPressed:()=>_show(context,existing:g)),IconButton(icon:const Icon(Icons.delete),onPressed:()=>appState.deleteGigIncome(g.id))]))));}))]);}),floatingActionButton:FloatingActionButton(onPressed:()=>_show(context),child:const Icon(Icons.add)),);}
