void _show(BuildContext context,{GigIncome? existing}){final appState=context.read<AppState>();final isEdit=existing!=null;GigPlatform plat=existing?.platform??GigPlatform.doordash;DateTime dt=existing?.date??DateTime.now();final base=TextEditingController(text:existing?.basePay.toString()??'');final tips=TextEditingController(text:existing?.tips.toString()??'');final bonus=TextEditingController(text:existing?.bonus.toString()??'');final miles=TextEditingController(text:existing?.miles.toString()??'');final mile=TextEditingController(text:existing?.mileage.toString()??'');final notes=TextEditingController(text:existing?.notes??'');showDialog(context:context,builder:(ctx){return StatefulBuilder(builder:(ctx,setSt){double b=double.tryParse(base.text)??0;double t=double.tryParse(tips.text)??0;double bo=double.tryParse(bonus.text)??0;double tot=b+t+bo;return AlertDialog(title:Text(isEdit?'Edit Gig Income':'Add Gig Income'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<GigPlatform>(initialValue:plat,items:GigPlatform.values.map((p){final tmp=GigIncome(id:'t',userId:'',householdId:'',date:DateTime.now(),platform:p,basePay:0,tips:0,bonus:0,mileage:0,miles:0,totalAmount:0);return DropdownMenuItem(value:p,child:Text(tmp.platformName));}).toList(),onChanged:(v)=>setSt(()=>plat=v??plat),decoration:const InputDecoration(labelText:'Platform')),Row(children:[Text('${dt.month}/${dt.day}/${dt.year}'),const Spacer(),TextButton(onPressed:()async{final pk=await showDatePicker(context:ctx,initialDate:dt,firstDate:DateTime(2020),lastDate:DateTime.now().add(const Duration(days:365)));if(pk!=null)setSt(()=>dt=pk);},child:const Text('Pick Date'))]),TextField(controller:base,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Base Pay'),onChanged:(_)=>setSt((){})),TextField(controller:tips,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Tips'),onChanged:(_)=>setSt((){})),TextField(controller:bonus,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Bonus'),onChanged:(_)=>setSt((){})),TextField(controller:miles,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Miles')),TextField(controller:mile,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Mileage Rate')),TextField(controller:notes,decoration:const InputDecoration(labelText:'Notes')),Text('Total: \$${tot.toStringAsFixed(2)}',style:const TextStyle(fontWeight:FontWeight.bold))])),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancel')),ElevatedButton(onPressed:(){final uid=appState.currentUser?.id??appState.currentUser?.householdId??'unknown';final hid=appState.currentUser?.householdId??uid;final g=GigIncome(id:existing?.id??DateTime.now().millisecondsSinceEpoch.toString(),userId:existing?.userId??uid,householdId:existing?.householdId??hid,date:dt,platform:plat,basePay:double.tryParse(base.text)??0,tips:double.tryParse(tips.text)??0,bonus:double.tryParse(bonus.text)??0,mileage:double.tryParse(mile.text)??0,miles:double.tryParse(miles.text)??0,totalAmount:tot,notes:notes.text,transactionId:existing?.transactionId);if(isEdit){appState.updateGigIncome(g);}else{appState.addGigIncome(g);}Navigator.pop(ctx);},child:Text(isEdit?'Update':'Save'))]);});});}
